// and w is invariant.
Matrix3d build_T_matrix(const Vector3d& i_vec, const Vector3d& j_vec) {
    Matrix3d T;
    T << 1.0, 0.0, 0.0,
         0.0, i_vec(0), i_vec(1),
         0.0, j_vec(0), j_vec(1);
    // Note: This assumes the global rotation components are (θx, θy) in global XY plane.
    // For fully 3D, we'd use full dot products with i_vec and j_vec (all 3 components),
    // but since nodes are coplanar and we only store θx,θy, we project onto XY.
    // More robust: use i_vec.dot(Vector3d(θx,θy,0)) etc., but θz=0.
    return T;
