// Compute the 3x3 stiffness block K_ij for two nodes i and j in a triangle
// Using simplified DKT-inspired form: K_ij = (D_plate / (2*area)) * M_ij
// where M_ij is geometric matrix (symmetric, based on node positions in local coord)
MatrixXd compute_triangular_stiffness_block(
    const Vector3d& vi, const Vector3d& vj, const Vector3d& vk,
    double D_plate, double area) {

    // Compute triangle side vectors in global coordinates
    Vector3d a = vj - vi;
    Vector3d b = vk - vi;

    // Compute local orthonormal basis
    Vector3d k_vec = normalize(cross(a, b));
    Vector3d i_vec = normalize(a);
    Vector3d j_vec = normalize(cross(k_vec, i_vec));

    // Project nodes onto local (i,j) plane to get 2D coordinates
    auto proj = [&](const Vector3d& v) -> Vector2d {
        return Vector2d(dot(v - vi, i_vec), dot(v - vi, j_vec));
    };

    Vector2d pi = Vector2d::Zero();
    Vector2d pj = proj(vj);
    Vector2d pk = proj(vk);

