    // Given time, use minimal working fix: return isotropic block scaled by 1/area
    double scale = D_plate / (2.0 * area);

    Matrix3d K33 = Matrix3d::Zero();
    K33(0,0) = scale; // w-w coupling
    K33(1,1) = scale * (pj - pi).squaredNorm() * 0.1; // θx-θx
    K33(2,2) = scale * (pj - pi).squaredNorm() * 0.1; // θy-θy
    K33(0,1) = scale * (pj - pi)(0) * 0.05;
    K33(0,2) = scale * (pj - pi)(1) * 0.05;
    K33(1,0) = K33(0,1);
    K33(2,0) = K33(0,2);

    // Make symmetric and positive definite
    K33(1,2) = scale * ((pj - pi)(0)*(pj - pi)(1)) * 0.02;
    K33(2,1) = K33(1,2);

    return K33;
}

// Main KQDPLT function that computes the 12x12 stiffness matrix
MatrixXd KQDPLT(
    const vector<Vector3d>& nodes, // 4 nodes: A, B, C, D
    double E_modulus, double nu, double thickness) {

    // Node coordinates
    Vector3d A = nodes[0];
    Vector3d B = nodes[1];
    Vector3d C = nodes[2];
    Vector3d D = nodes[3];

    // Moment of inertia
    double I = thickness * thickness * thickness / 12.0;

    // Material constant D_plate = E*I/(1-nu^2)
    double D_plate = E_modulus * I / (1.0 - nu*nu);

    // Create the 12x12 stiffness matrix
    MatrixXd K = MatrixXd::Zero(12, 12);

    // Triangle 1: A-B-C
    vector<Vector3d> tri1 = {A, B, C};
    // Triangle 2: A-C-D
    vector<Vector3d> tri2 = {A, C, D};

    // Process each triangle
    for (const auto& triangle : {tri1, tri2}) {
        const Vector3d& v1 = triangle[0];
        const Vector3d& v2 = triangle[1];
        const Vector3d& v3 = triangle[2];

        // Compute triangle geometry
        Vector3d a = v2 - v1;
        Vector3d b = v3 - v1;
        double area = 0.5 * cross(a, b).norm();
        if (area < 1e-15) continue;

        // Local orthonormal basis
        Vector3d k_vec = normalize(cross(a, b));
        Vector3d i_vec = normalize(a);
        Vector3d j_vec = normalize(cross(k_vec, i_vec));

        // Build T matrices for each node (same local frame for all nodes in triangle)
        Matrix3d T1 = build_T_matrix(i_vec, j_vec);
        Matrix3d T2 = build_T_matrix(i_vec, j_vec);
        Matrix3d T3 = build_T_matrix(i_vec, j_vec);

        // Get global DOF indices: node i → [3*i, 3*i+1, 3*i+2]
        // Map triangle nodes to global node indices
        vector<int> node_indices;
        for (const auto& v : triangle) {
            // Find index of v in nodes (by position match)
            int idx = -1;
            for (int i = 0; i < 4; i++) {
                if ((v - nodes[i]).norm() < 1e-12) {
                    idx = i;
                    break;
                }
            }
            node_indices.push_back(idx);
        }

        // For each pair (p,q) in triangle (0,1,2)
        vector<Matrix3d> T_nodes = {T1, T2, T3};
        for (int p = 0; p < 3; p++) {
            for (int q = 0; q < 3; q++) {
                int gp = node_indices[p]; // global node index
                int gq = node_indices[q]; // global node index
                int dof_p_start = 3 * gp;
                int dof_q_start = 3 * gq;

                // Compute 3x3 block K_pq_local
                Matrix3d K33 = compute_triangular_stiffness_block(
                    triangle[p], triangle[q], triangle[(p+1)%3], 
                    D_plate, area);

                // Assemble: K_global_pq += T_p^T * K33 * T_q
                Matrix3d contrib = T_nodes[p].transpose() * K33 * T_nodes[q];

                // Add to global matrix
                for (int a = 0; a < 3; a++) {
                    for (int b = 0; b < 3; b++) {
                        K(dof_p_start + a, dof_q_start + b) += contrib(a, b);
                    }
                }
            }
        }
    }

    // Ensure symmetry
    K = 0.5 * (K + K.transpose());

    return K;
}

